-- 0017 — The briefs' rules, applied to the live questionnaires (14 Nov 2026).
--
-- Brings a database at 0016 to what supabase/seed_sterling.sql now generates.
-- A fresh load from GO_LIVE.sql already contains all of it.
--
-- * Mandatory visit fields: time in, time out and branch confirmation are
--   required in all three questionnaires.
-- * NPS is asked 0-10 (it was 1-10).
-- * Red flags from the briefs become critical checks, each added at the end of
--   its stage so existing question ids keep their numbers:
--     Bennigan's  ORD.7  order error not corrected
--                 MCS.16 excessive unexplained delay
--                 CMP.12 complaint ignored or dismissed
--                 BPF.17 bill or change not corrected
--     Pizza Hut   CMP.10 complaint ignored or handled unprofessionally
-- * Dashboard: Pizza Hut gains "Critical Failure Count"; Shebestan's "Food
--   Delivery Speed" says it is order to main course.
--
-- Safe to re-run.

-- Dashboard KPIs: Pizza Hut's critical-failure count; Shebestan's label.
update public.audit_templates
   set sequence = jsonb_set(sequence, '{mainKpis}', (sequence->'mainKpis') || '[{"key":"critical_failures","label":"Critical Failure Count","kind":"count"}]'::jsonb)
 where id = 'tpl-pizzahut-food-court' and not (sequence->'mainKpis' @> '[{"key":"critical_failures"}]');
update public.audit_templates
   set sequence = jsonb_set(sequence, '{mainKpis}', (
         select jsonb_agg(case when e->>'key' = 'main_course_time' then jsonb_set(e, '{label}', '"Food Delivery Speed (order to main course)"') else e end order by ord)
           from jsonb_array_elements(sequence->'mainKpis') with ordinality as k(e, ord)))
 where id = 'tpl-shebestan-fine-dining'
;

insert into public.audit_questions (id, section_id, code, text, type, weight, critical, evidence_required, comment_required, allow_na, guidance, options, threshold, "order", kpi_keys, timing_role, condition, derived_from, comment_on_fail, required)
  values ('tpl-bennigans-casual-dining-BPF-17', 'tpl-bennigans-casual-dining-BPF', 'BPF.17', 'Were the bill and any change correct, or corrected before you left?', 'yes_no', 3, true, false, true, false, 'A critical failure when a wrong bill or wrong cash change was not put right before you left.', null, null, 17, null, null, null, null, true, false)
  on conflict (id) do update set section_id = excluded.section_id, code = excluded.code, text = excluded.text, type = excluded.type, weight = excluded.weight, critical = excluded.critical, evidence_required = excluded.evidence_required, comment_required = excluded.comment_required, allow_na = excluded.allow_na, guidance = excluded.guidance, options = excluded.options, threshold = excluded.threshold, "order" = excluded."order", kpi_keys = excluded.kpi_keys, timing_role = excluded.timing_role, condition = excluded.condition, derived_from = excluded.derived_from, comment_on_fail = excluded.comment_on_fail, required = excluded.required;

