update public.audit_templates t
   set question_count = (select count(*) from public.audit_questions q join public.audit_sections s on s.id = q.section_id where s.template_id = t.id)
 where t.id in ('tpl-shebestan-fine-dining', 'tpl-bennigans-casual-dining', 'tpl-pizzahut-food-court');
